import{_ as e,c as i,o,ag as a}from"./chunks/framework.C8hRoDJf.js";const b=JSON.parse('{"title":"游戏更新日志","description":"","frontmatter":{},"headers":[],"relativePath":"changelog/detail.md","filePath":"changelog/detail.md"}'),t={name:"changelog/detail.md"};function r(c,l,d,u,n,h){return o(),i("div",null,l[0]||(l[0]=[a('<h1 id="游戏更新日志" tabindex="-1">游戏更新日志 <a class="header-anchor" href="#游戏更新日志" aria-label="Permalink to &quot;游戏更新日志&quot;">​</a></h1><h2 id="版本-2026-第-二-季度" tabindex="-1">版本 2026 第 二 季度 <a class="header-anchor" href="#版本-2026-第-二-季度" aria-label="Permalink to &quot;版本 2026 第 二 季度&quot;">​</a></h2><blockquote><p>游戏设定调整</p></blockquote><ul><li>[🚀] 威望商店新增售卖道具——玛雅宝宝之卵、鬼精灵欧姆白之卵，鬼精灵欧姆黑之卵。</li><li>[🚀] 宠物合成新增合成公式（添加至尊神石100%成功）—— <ul><li>鬼精灵欧姆金：鬼精灵欧姆 + 金龙霸王</li><li>鬼精灵欧姆绿：鬼精灵欧姆 + 青龙琅琅</li><li>鬼精灵欧姆蓝：鬼精灵欧姆 + 冰龙苍海</li><li>鬼精灵欧姆粉：鬼精灵欧姆 + 炎龙血焰</li><li>鬼精灵欧姆紫：鬼精灵欧姆 + 黄龙莫虚。</li></ul></li><li>[🔧] 修复了神宠转生时，涅磐兽转生条件不足的消息提示。</li></ul><h2 id="版本-2026-第-一-季度" tabindex="-1">版本 2026 第 一 季度 <a class="header-anchor" href="#版本-2026-第-一-季度" aria-label="Permalink to &quot;版本 2026 第 一 季度&quot;">​</a></h2><blockquote><p>游戏设定调整</p></blockquote><ul><li>[🚀] 威望商店新增售卖道具——蜥蜴拳皇之卵。</li></ul><blockquote><p>服务器优化</p></blockquote><ul><li>[🔧] 对游戏过程中，出现异常数据现象且未加入游戏交流群的玩家进行屏蔽（无法正常登入游戏），被屏蔽玩家需要主动联系客服承诺自己会在游戏过程中拒绝使用任何第三方工具，不进行违规游戏行为，申请解除屏蔽。</li></ul><h2 id="版本-2025-第-四-季度" tabindex="-1">版本 2025 第 四 季度 <a class="header-anchor" href="#版本-2025-第-四-季度" aria-label="Permalink to &quot;版本 2025 第 四 季度&quot;">​</a></h2><blockquote><p>服务器优化</p></blockquote><ul><li>[🚀] 更换了服务器操作系统。</li><li>[🔧] 优化了游戏服务端的运行时指标监控机制（不涉及玩家个人信息）。</li><li>[🔧] 增加了聊天系统玩家异常连接的日志记录（包括响应超时、错误关闭、长期断开后重连、频繁连接情况）。</li></ul><h2 id="版本-2025-第-三-季度" tabindex="-1">版本 2025 第 三 季度 <a class="header-anchor" href="#版本-2025-第-三-季度" aria-label="Permalink to &quot;版本 2025 第 三 季度&quot;">​</a></h2><blockquote><p>游戏设定调整</p></blockquote><ul><li>[🚀] 威望商店新增售卖道具——修炼仙册(60 威望 / 每本)。</li><li>[🚀] 降低了<code>摩卡志</code>图标收集难度。 <ul><li><strong>收集狂</strong>：拥有 1kw 金币、3000 威望、3000 水晶。</li><li><strong>新大陆地图</strong>：降低击杀 BOSS 次数为 10 次。</li></ul></li><li>[🚀] 增加了<code>自然女神</code>、<code>暗夜女神</code>的技能效果（技能附带 12% —&gt; 15% 伤害加深效果）。</li><li>[🚀] 降低了<code>召唤寒江雪之书</code>的使用要求（收集 699 -&gt; 600 个天界的精髓）。</li><li>[📉] 降低了部分道具的使用效果。 <ul><li><strong>玉露结晶</strong>调整为使用后增加 0.1~0.4 成长。</li><li><strong>天仙玉露</strong>调整为使用后增加 0.5~0.8 成长。</li></ul></li><li>[📈] 增加了<code>新手基地</code>、<code>妖精森林</code>、<code>潮汐海崖</code>的进化道具掉落几率。</li><li>[🔧] 副本地图等待界面显示当前副本难度。</li></ul><hr><blockquote><p>服务器优化</p></blockquote><ul><li>[🔧] 修复了游戏指南的部分错误及新增部分信息。</li><li>[🔧] 更新了宠物图鉴的调整后宠物技能效果。</li><li>[🚀] 优化了服务器的配置（不涉及玩家数据）。</li></ul><h2 id="版本-2025-第-二-季度" tabindex="-1">版本 2025 第 二 季度 <a class="header-anchor" href="#版本-2025-第-二-季度" aria-label="Permalink to &quot;版本 2025 第 二 季度&quot;">​</a></h2><blockquote><p>网站链接调整</p></blockquote><ul><li>[🔧] 调整<code>宠物图鉴</code>访问地址为：<a href="http://127.0.0.1:12000/atlas" target="_blank" rel="noreferrer">http://127.0.0.1:12000/atlas</a>，弃用旧地址。</li><li>[🔧] 调整<code>游戏指南</code>访问地址为：<a href="http://127.0.0.1:12000/docs" target="_blank" rel="noreferrer">http://127.0.0.1:12000/docs</a>，弃用旧地址。</li><li>[🔧] 限制了请求来源，对不合理的页面请求来源进行了屏蔽，请从 <strong><a href="http://127.0.0.1:12000" target="_blank" rel="noreferrer">http://127.0.0.1:12000</a></strong> 访问游戏及相关服务。</li></ul><hr><blockquote><p>游戏设定调整</p></blockquote><ul><li>[🚀] 玩家登录有效期（下次刷新页面无需输入账号密码）由<code>7天</code>调整为<code>14天</code>。</li><li>[🚀] 优化客户端版本更新机制。 <ul><li>当需要进行游戏严重漏洞修复，无法与前一个版本兼容的内容更新时。客户端会接受到服务器的最新的更新推送通知，并自动进行页面刷新（这意味着处于挂机状态下的玩家会自动退出挂机状态，并加载最新版本的内容）。</li><li>其他场景下的游戏更新方式：玩家自行刷新游戏页面加载新内容。</li></ul></li><li>[🔧] 野外探险处于自动战斗状态时，进入下一轮等待时长调整为恒定 5s。 <ul><li>玩家处于自动战斗状态下，无论是否点击【继续冒险】，下一轮怪物的刷新时长为 5s。</li><li>玩家不处于自动状态下，手动点击【继续探险】，下一轮怪物的刷新时长为 1s。</li></ul></li></ul><hr><blockquote><p>服务器优化</p></blockquote><ul><li>[🚀] 优化了资源缓存机制。部分浏览器支持二次请求静态资源时直接从玩家本地缓存获取，无需再次下载服务器资源。</li><li>[🚀] 增加了网页性能监控机制，用户访问游戏时，会有网络请求用于收集 Google 官方列出的页面性能指标数据。</li><li>[🔧] 统计玩家游戏过程中在页面的点击事件进行上报，<strong>不会</strong>记录玩家游戏过程及操作路径，当前记录<code>点击次数</code>、<code>点击时间</code>、<code>页面坐标x,y像素点</code>。</li><li>[🔧] 上报玩家游戏过程中代码的执行错误、违反正常游戏行为的操作进行上报（时间模块）。</li><li>[🔧] 优化了网站访问日志，这部分日志只对异常访问、爬虫访问、短时间内高频率访问 IP 进行数据分析统计。</li></ul><h2 id="版本-2025-第-一-季度" tabindex="-1">版本 2025 第 一 季度 <a class="header-anchor" href="#版本-2025-第-一-季度" aria-label="Permalink to &quot;版本 2025 第 一 季度&quot;">​</a></h2><ol><li>[🔧] 调整所有道具购买/售卖价格、商店售卖道具种类、部分野外地图掉落，部分任务需求。</li><li>[🔧] 调整了地图相关宠物技能效果、部分道具价格及礼包几率。</li><li>[🚀] 增加了新的任务及道具。</li><li>[🚀] 调整了背包及仓库的道具、任务列表的优先级顺序。</li><li>[🚀] 优化了<code>自动战斗</code>功能，部分 PC 及移动端浏览器支持后台自动战斗（无需设置浏览器性能模式）。</li><li>[🚀] 优化了游戏资源加载的提示动画与提示信息。</li><li>[🔧] 加强了游戏玩家用户信息及隐私相关的保障。</li></ol><h2 id="版本-2024-第-四-季度" tabindex="-1">版本 2024 第 四 季度 <a class="header-anchor" href="#版本-2024-第-四-季度" aria-label="Permalink to &quot;版本 2024 第 四 季度&quot;">​</a></h2><ol><li>[🚀] 调整了野外、副本地图掉落奖励。</li><li>[🚀] 调整了任务数量和完成奖励。</li><li>[🚀] 调整礼包开启道具详情与几率。</li></ol><h2 id="感谢您的支持" tabindex="-1">感谢您的支持！ <a class="header-anchor" href="#感谢您的支持" aria-label="Permalink to &quot;感谢您的支持！&quot;">​</a></h2><p>感谢所有玩家的反馈与支持，开发者会继续努力为大家带来更好的游戏体验！</p>',33)]))}const p=e(t,[["render",r]]);export{b as __pageData,p as default};
